 @PostMapping("/attendance") synchronized Map<String,Object> saveAttendance(@RequestBody Map<String,Object>b,HttpServletRequest r){long a=actor(r);String d=date(b,"date"),m=month(d.substring(0,7));attendanceOpen(m);long employee=num(b,"employee_id");available("contacts",employee);if(!str(one("contacts",employee),"kind").equals("EMPLOYEE"))throw new Fail(400,"Chọn nhân viên để chấm công");String status=choice(str(b,"status"),"WORK","HALF","PAID_LEAVE","UNPAID_LEAVE","OFF");long overtime=num(b,"overtime_minutes");if(overtime<0||overtime>960||overtime%15!=0)throw new Fail(400,"Tăng ca từ 0 đến 16 giờ, theo bước 15 phút");if(overtime>0&&!List.of("WORK","HALF").contains(status))throw new Fail(400,"Chỉ ghi tăng ca vào ngày có đi làm");String note=str(b,"note");if(note.length()>2000)throw new Fail(400,"Ghi chú quá dài");return tx.execute(t->{var rows=db.queryForList("SELECT * FROM attendance WHERE employee_id=? AND date=?",employee,d);var old=rows.isEmpty()?null:rows.get(0);long id=old==null?0:num(old,"id");if(old!=null&&num(old,"deleted")==0&&num(b,"version")!=num(old,"version"))throw new Fail(409,"Công đã thay đổi. Tải lại bảng công.");if((old==null||num(old,"deleted")==1)&&num(b,"version")!=0)throw new Fail(409,"Công đã thay đổi. Tải lại bảng công.");if(old!=null)required(b,"reason");if(old==null){db.update("INSERT INTO attendance(employee_id,date,status,overtime_minutes,note,created_by,updated_by) VALUES(?,?,?,?,?,?,?)",employee,d,status,overtime,note,a,a);id=last();}else db.update("UPDATE attendance SET status=?,overtime_minutes=?,note=?,deleted=0,version=version+1,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",status,overtime,note,a,id);var saved=one("attendance",id);audit(a,old==null?"ATTENDANCE_CREATE":"ATTENDANCE_UPDATE","attendance",id,old,saved,str(b,"reason"));return saved;});}
