 @GetMapping("/vouchers") synchronized List<Map<String,Object>> vouchers(HttpServletRequest r){auth(r,false);return db.queryForList("SELECT v.*,f.name fund_name,g.name to_fund_name,c.name contact_name,k.name category_name FROM vouchers v JOIN funds f ON f.id=v.fund_id LEFT JOIN funds g ON g.id=v.to_fund_id LEFT JOIN contacts c ON c.id=v.contact_id LEFT JOIN categories k ON k.id=v.category_id ORDER BY v.date DESC,v.id DESC");}
